  <div class="chrome">
    <button class="nav-btn" data-prev aria-label="Previous slide">‹</button>
    <span class="counter" data-counter>01 / 13</span>
    <button class="nav-btn" data-next aria-label="Next slide">›</button>
    <button class="nav-btn" data-fullscreen aria-label="Toggle fullscreen">⛶</button>
  </div>

  <script>
    (function () {
      var slides = Array.prototype.slice.call(document.querySelectorAll('.slide'));
      var total = slides.length;
      if (!total) return;

      var counter = document.querySelector('[data-counter]');
      var progress = document.querySelector('[data-progress]');
      var index = 0;

      function pad(n) { return String(n).padStart(2, '0'); }

      function render() {
        slides.forEach(function (s, i) { s.classList.toggle('active', i === index); });
        if (counter) counter.textContent = pad(index + 1) + ' / ' + pad(total);
        if (progress) progress.style.transform = 'scaleX(' + ((index + 1) / total) + ')';
        if (history.replaceState) history.replaceState(null, '', '#' + (index + 1));
        else location.hash = '#' + (index + 1);
      }

      function go(i) { index = Math.max(0, Math.min(total - 1, i)); render(); }
      function next() { go(index + 1); }
      function prev() { go(index - 1); }

      function toggleFullscreen() {
        if (!document.fullscreenElement) {
          if (document.documentElement.requestFullscreen) document.documentElement.requestFullscreen();
        } else if (document.exitFullscreen) {
          document.exitFullscreen();
        }
      }

      document.addEventListener('keydown', function (e) {
        var k = e.key;
        if (k === 'ArrowRight' || k === 'ArrowDown' || k === 'PageDown' || k === ' ') {
          e.preventDefault(); next();
        } else if (k === 'ArrowLeft' || k === 'ArrowUp' || k === 'PageUp') {
          e.preventDefault(); prev();
        } else if (k === 'Home') { e.preventDefault(); go(0); }
        else if (k === 'End') { e.preventDefault(); go(total - 1); }
        else if (k === 'f' || k === 'F') { toggleFullscreen(); }
        else if (k === 's' || k === 'S') { document.body.classList.toggle('notes-on'); }
      });

      document.querySelectorAll('[data-next]').forEach(function (b) { b.addEventListener('click', next); });
      document.querySelectorAll('[data-prev]').forEach(function (b) { b.addEventListener('click', prev); });
      document.querySelectorAll('[data-fullscreen]').forEach(function (b) { b.addEventListener('click', toggleFullscreen); });

      var startX = null;
      document.addEventListener('touchstart', function (e) { startX = e.touches[0].clientX; }, { passive: true });
      document.addEventListener('touchend', function (e) {
        if (startX === null) return;
        var dx = e.changedTouches[0].clientX - startX;
        if (Math.abs(dx) > 50) { dx < 0 ? next() : prev(); }
        startX = null;
      }, { passive: true });

      var fromHash = parseInt((location.hash || '').replace('#', ''), 10);
      if (!isNaN(fromHash)) index = Math.max(0, Math.min(total - 1, fromHash - 1));
      render();
    })();
  </script>
</body>
</html>
